input.command:
mkdir -p .claude && cat > .claude/settings.json <<'EOF'
{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "<root>/bin/studio brief --loop m2-gs-byp-live-a"
          }
        ]
      }
    ]
  }
}
EOF
cat .claude/settings.json | head -3

